// Fixtures produced by unmodified a55uka/nup d40d9cf with zstandard 0.25.0.
// Stored as small text constants so tests require no network or Python runtime.
import XCTest
@testable import NUPStudio

extension NUPCoreTests {
    func testPythonReferenceContainer() throws {
        let fixture = Data(base64Encoded: "")!
        let url = try write("python.nup", fixture)
        let archive = try NUPArchive(url: url)
        XCTAssertEqual(archive.packages[0].titleIDString, "040074A01BF12000")
        XCTAssertEqual(String(data: archive.packages[0].metadata[4] ?? Data(), encoding: .utf8), "Python reference")
        XCTAssertEqual(String(data: archive.packages[0].metadata[5] ?? Data(), encoding: .utf8), "Upstream")
        XCTAssertTrue(archive.files.contains { $0.codec == 0 && $0.size > 0 })
        XCTAssertTrue(archive.files.contains { $0.codec == 1 })
        try archive.verify(deep: true, context: JobContext())
        let target = root.appendingPathComponent("python-extracted")
        try archive.extract(package: 0, subtree: nil, destination: target, context: JobContext())
        XCTAssertEqual(try Data(contentsOf: target.appendingPathComponent("romfs/compressed")), Data(String(repeating: "Cross-language NUP\n", count: 1000).utf8))
    }
    func testPythonReferenceLargeStreamingFrame() throws {
        let fixture = Data(base64Encoded: "")!
        let url = try write("python-large.nup", fixture)
        let archive = try NUPArchive(url: url)
        XCTAssertEqual(archive.files[0].size, 270 * 1024 * 1024)
        XCTAssertEqual(archive.files[0].codec, 1)
        try archive.verify(deep: true, context: JobContext())
    }
}
